function CertifyRecovery(T[0..n-1], N[0..n-1], tau, eps):
    eps_obs <- 0
    m_obs   <- +infinity
    for i in 0..n-1:
        pT <- T[i].death - T[i].birth
        pN <- N[i].death - N[i].birth
        eps_obs <- max(eps_obs, |pN - pT|)
        m_obs   <- min(m_obs, |pT - tau|)
    R <- m_obs / (2 * eps)
    certified <- (eps_obs <= eps) and (2 * eps < m_obs)
    return (certified, R)

function BettiCount(B[0..n-1], tau):
    count <- 0
    for i in 0..n-1:
        if tau < (B[i].death - B[i].birth):
            count <- count + 1
    return count
